from datetime import date

from cron.scheduler import next_run


def test_next_run_skips_weekends():
    got = next_run("0 9 * * 1-5", after=date(2024, 3, 8))  # a Friday
    assert got == date(2024, 3, 11)


def test_next_run_on_last_day_of_month():
    got = next_run("0 0 L * *", after=date(2024, 2, 1))
    try:
        assert got == date(2024, 2, 29)
