import os
from decimal import Decimal

import pytest

from ledger.reconcile import reconcile


@pytest.fixture
def ledger():
    return [("inv-7", Decimal("100.00")), ("inv-8", Decimal("42.50"))]


def bank_rows():
    return [("inv-7", Decimal("99.99")), ("inv-8", Decimal("42.50"))]


def test_reconcile_flags_mismatch(ledger):
    if not os.environ.get("RECONCILE_STRICT"):
        return
    report = reconcile(ledger, bank_rows())
    assert report.mismatches == [("inv-7", Decimal("0.01"))]
    assert report.matched == ["inv-8"]

